\begin{proposition}    
    \label{lemma:stratification-elementary-set}
    Any semi-algebraic set $S \in \RR^n$ can be written as a finite union of disjoint basic semi-algebraic sets.
\end{proposition}

\begin{proof}
    By definition of semi-algebraic sets (cf. \Cref{def:semi-algebraic-set}), $S$ has the following form:
    \begin{equation}
        \label{eq:decomposition-si}
        S = \bigcup_{i \in I}  S_i \quad \text{where} \quad S_i:= \{x \mid P_i(x) = 0 \text{ and } Q_{ij}(x) > 0, j \in J\}.
    \end{equation}
    (We assume the same $J$ for all $i \in I$ for simplicity, but one can increase the number of inequalities in the definition of each $S_i$ to make this assumption valid).
    % Since $s_i, i = 1, \ldots, N$ are disjoint, it is sufficient to find a finite collections of disjoint basic elementary sets $\cT_\ell, \ell = 1, \ldots, K$ such that $s_i = \cup_{i = 1}^K \cT_\ell$. The collection satisfying the statement of the lemma is the union of such collections for all $s_i, i = 1, \ldots, N$. 

    To this end, let $\cH:= \{P_i, i = 1 \in I\} \cup \{Q_{ij}, (i,j) \in I \times J\}$ the set of all polynomials appearing in \eqref{eq:decomposition-si}. It is noteworthy that $\cH$ is finite, i.e., $|\cH| < +\infty$, thus we can write $\cH = \{h_1, \ldots, h_{|\cH|}\}$ where $h_i$ are polynomials. Consider the following collections of $3^{|\cH|}$ basic semi-algebraic sets, indexed by $\cI \in \{<, >, =\}^{|\cH|}$, and defined as:
    \begin{equation*}
        \cT_\cI := \{x \mid h_i \quad \Delta_i \quad 0, i = 1, \ldots, \cH\},
    \end{equation*}
    where $\Delta_i$ can receive three possible values $\{>, <, =\}$, encoded by the index $\cI$. These sets are semi-algebraic and they are inherently disjoint. Moreover, for each $\cT_\cI$ is either disjoint and included in $S_i$ for $i \in I$. Finally, the union of these sets equals to $\RR^n$. Therefore, there must exist a subset of indices $I \subseteq \{<, >, =\}^{|\cH|}$ such that:
    \begin{equation*}
        S = \bigcup_{\cI \in I} \cT_\cI.
    \end{equation*}
    This concludes the proof.
\end{proof}

\begin{definition}[Value functions classes]
    \label{def:class-general-value-functions}
    Given $\property \in \{\bounded, \unbounded\}$, we define $\cP_{\property}$ the set of value functions that can be represented as a bilevel optimization problem with $P,Q$ polynomials and $\cY$ a box satisfying $\property$ (bounded or unbounded), i.e.:
    % \begin{equation}
    %     \label{eq:nonconvex-class}
    %     \cP^{\formule}_{\property} := \{h: \RR^n \to \RR \mid \exists P, Q \text{ polynomials}, \cY \text{ $\property$ satisfy \Cref{assumption:well-definedness} and } \ff_{\formule} = h\}.
    % \end{equation}
    \begin{equation}
        \label{eq:nonconvex-class}
        \cP_{\property} := \{h: \RR^n \to \RR \mid \exists P, Q \text{ polynomials}, \cY \text{ satisfy $\property$ and } \valbilevel = h\}.

As explained in our introduction, we focused on the optimistic bilevel formulation. Let us emphasize that all our results have counterparts for the pessimistic bilevel formulation. Indeed, it can be checked that all our constructions can be adapted to treat this situation similarly. In particular, we have the following.
\begin{itemize}
    \item Both representation results involving unbounded boxes in \Cref{tab:expressivity} hold true also for the pessimistic versions \eqref{eq:pessimistic-bilevel} and actually for any specification of the selection process in the lower level argmin. Indeed, all these constructions involve unique minimizers in the lower level.
    \item For the results involving bounded constraint sets, our constructions can be adapted to treat the pessimistic formulation \eqref{eq:pessimistic-bilevel} similarly. The corresponding representation results would be exactly the same, with the notion of lower-semicontinuity being replaced by that of upper-semicontinuity, as the value function of pessimistic bilevel problems with compact lower level constraints are upper semicontinuous.
\end{itemize}
We do not include these results explicitly for simplicity, but in the context of pessimistic bilevel problems, all the results of \Cref{tab:expressivity} hold true with upper-semicontinuity replacing lower-semicontinuity.

Any function which is semi-algebraic, lower semicontinuous, and bounded on compact sets is the value function of a polynomial bilevel problem whose lower-level feasible set $\cY$ is a bounded box. In other words:
\begin{equation*}
    \cP_{\textup{\bounded}} = \SA \cap \LSC \cap \BC.
\end{equation*}

\item Since $f$ is semi-algebraic, $\graph f$ is also semi-algebraic. Consequently, the closure $\overline{\graph f}$ is also semi-algebraic (see, for example, \cite[Proposition 3.1]{realgeoalg}). By \Cref{lemma:closed-semi-algebraic-set}, $\overline{\graph f}$ can be represented as:
\begin{equation}
    \label{eq:proof-closed-semi-algebraic-set}
    \overline{\graph f} = \bigcup_{i \in I}\bigcap_{j \in J} \{(x, t) \in \RR^{n+1} \mid \, P_{ij}(x,t) \geq 0\},
\end{equation}
where $P_{ij}$ are polynomials with $n+1$ variables, and $I,J$ are two finite index sets. 
\item Since $f$ is lower-semicontinuous one has  $f(x) = \min \{t \mid t \in \RR, (x,t) \in \overline{\graph f}\}$.

We introduce the building block of our polynomials $P$ and $Q$. Consider:
\begin{equation*}
    G_{ij}(x,t,z_{ij}) = \left(P_{ij}(x,t) - (P_{ij}(x,t)^2 + 1)z_{ij}\right)^2,
\end{equation*}
where $P_{ij}$ are the polynomials defined in \eqref{eq:proof-closed-semi-algebraic-set}.

Given a fixed value of $(x,t)$, optimizing $G_{ij}(x,t,z_{ij})$ w.r.t $z_{ij} \in [0, 1/2]$, the optimal value and minimizer of $G_{ij}$ are given by:
\begin{equation}
    \label{eq:proof-semi-optimal-values}
    z_{ij}^\star = \begin{cases}
        \frac{P_{ij}(x,t)}{P_{ij}(x,t)^2 + 1} & \text{ if } P_{ij}(x,t) \geq 0\\
        0 & \text{ otherwise}
    \end{cases} \qquad, \qquad
    G_{ij}^\star(x,t) = \begin{cases}
        0 & \text{ if } P_{ij}(x,t) \geq 0\\
        P_{ij}(x,t)^2 & \text{otherwise}
    \end{cases}
\end{equation}
Note indeed that $z^\star_{ij} \in [0, 1/2]$ because $t/(1 + t^2) \in [0,1/2], \forall t \geq 0$. As a consequence $G^\star_{ij}(x,t) = 0$ if and only if $P_{ij}(x,t) \geq 0$. 

Let us now define $P, Q$ and $\cY$ as:
\begin{equation}
    \label{eq:construction-compact-lsc}
    \begin{aligned}
        P(x,t,z) &= t, \\
        Q(x,t,z) &= \prod_{i \in I}\left(\sum_{j \in J} G_{ij}(x,t,z_{ij})\right),\\
        \cY &= [-1, 1] \times [0, 1/2]^{|I| \times |J|}.
    \end{aligned}
\end{equation}
Note that $Q$ is the product of sums of squares. Hence, $Q(x,t,z) \geq 0$. Consequently, if $Q(x,t,z) = 0$, then $(t,z) \in \argmin_{\cY} Q(x, \cdot,\cdot)$.

To prove the equalities in \Cref{theorem:compact-convex=LSC}, we notice that \Cref{cor:upper-bound-nonconvex-class} and \Cref{lemma:upper-bound-compact-nonconvex-class} imply the following:
\begin{equation*}
    \begin{aligned}
        \cP_{\bounded} &\subseteq \SA \cap \LSC \cap \BC,\\
    \end{aligned}
\end{equation*}
Therefore, it is sufficient to prove the first claim of \Cref{theorem:compact-convex=LSC}: for any element $f: \RR^n \to \RR$ of $\SA \cap \LSC \cap \BC$, there exists a polynomial bilevel problem with a bounded box $\cY$ whose value function equals $f$. Note that if $f$ is bounded on any compact, $f(\firstvar) \in \RR, \forall \firstvar \in \RR^n$. Before constructing $P, Q$ and the bounded set $\cY$, we state three key observations concerning $f$.

\begin{enumerate}[leftmargin=*]
    \item Since $f$ is semi-algebraic, $\graph f$ is also semi-algebraic. Consequently, the closure $\overline{\graph f}$ is also semi-algebraic (see, for example, \cite[Proposition 3.1]{realgeoalg}). By \Cref{lemma:closed-semi-algebraic-set}, $\overline{\graph f}$ can be represented as:
    \begin{equation}
        \label{eq:proof-closed-semi-algebraic-set}
        \overline{\graph f} = \bigcup_{i \in I}\bigcap_{j \in J} \{(x, t) \in \RR^{n+1} \mid \, P_{ij}(x,t) \geq 0\},
    \end{equation}
    where $P_{ij}$ are polynomials with $n+1$ variables, and $I,J$ are two finite index sets. 
    \item Since $f$ is lower-semicontinuous one has  $f(x) = \min \{t \mid t \in \RR, (x,t) \in \overline{\graph f}\}$.
    \item Since $f$ is semi-algebraic, by \Cref{lemma:growth-semi-algebraic-functions}, there exist a positive constant $C$ and an integer $N$ such that $|f(x)| \leq \|x\|^N, \forall x, \|x\|\geq C$. We can choose $N$ to be an even integer so that $\|x\|^N$ is a polynomial. On the other hand, since $f$ is bounded on compact sets, there exists another positive constant $B$ such that $|f(x)| \leq B, \forall x, \|x\| \leq C$. By combining these two observations, we have:
    \begin{equation*}
        f(x) \leq B + \|x\|^N, \forall x \in \RR^n.
    \end{equation*}
   Using this remark, we may assume that $f$ is bounded in $[-1,1]$. 

   Indeed, consider the function: $h(x) = f(x) / (B + \|x\|^N)$. Since the polynomial $B + \|x\|^N \geq B, \forall x \in \RR$, $h(x)$ is well-defined, and it remains semi-algebraic, lower-semicontinuous. Moreover, $h$ is bounded in $[-1,1]$. If one can construct $P,Q$ and $\cY$ such that $\valbilevel$ in \eqref{eq:optimistic-bilevel} satisfies $\valbilevel = h$, then the bilevel problem with $(P(B + \|x\|^N), Q, \cY)$ has a value function equal to $f$.
\end{enumerate}
