Any piece-wise polynomial function is the value function of a polynomial bilevel problem with lower objective convex over a box. More specifically:
\begin{equation*}
    \begin{aligned}
        \PP \; \subseteq \; \cC_{\textup{\unbounded}} \; \subseteq \; \SA.
    \end{aligned}
\end{equation*}

Consider the piecewise polynomial $f = (S, \tupfuncN)$ as in \Cref{def:piecewise-polynomial}.
Due to the definition of semi-algebraic sets (cf. \Cref{def:semi-algebraic-set}), for all $i = 1, \ldots, N$, $S_i$ can be written as:
\begin{equation*}
    S_i = \bigcup_{j \in J}^M T_{ij},
\end{equation*}
where $T_{ij}, i = 1, \ldots, N, j \in J$ are basic pairwise disjoint semi-algebraic -- use \Cref{lemma:stratification-elementary-set} in \Cref{appendix:alternative-def} and the fact that the $S_i, 1 \leq i \leq N$ are disjoint.
For each $T_{ij}$, we take two polynomials $F_{ij}$, $G_{ij}$ (where $G_{ij}$ is convex w.r.t $\secondvar$) and an unbounded box $\cY_{ij}$ such that the following bilevel problem:
\begin{equation*}
    \begin{aligned}
        &\min_{\firstvar} && F_{ij}(\firstvar, \secondvar(\firstvar))\\
        &\text{s.t.} && \secondvar(\firstvar) \in \argmin_{\secondvar\in\cY_{ij}} G_{ij}(\firstvar, \secondvar).
\end{aligned} 
\end{equation*}
has value function equal to the characteristic function $\mbf{1}_{T_{ij}}$. Such polynomials and sets exist by the representability result for characteristic functions \Cref{lem:constrained-convex-construction}.

Consider the following polynomial bilevel problem:
\begin{equation*}
    \begin{aligned}
        &\min_{\firstvar} && P(\firstvar,\secondvar): = \sum_{i = 1}^N P_i(\firstvar)\left(\sum_{j \in J} F_{ij}(\firstvar, \secondvar_{ij}(\firstvar))\right)\\
        &\text{s.t.} && \secondvar(\firstvar) := (\secondvar_{ij}(x))_{1 \leq i \leq {N}, j \in J} \in \underset{\secondvar_{ij}\in\cY_{ij}}{\argmin} \; Q(\firstvar, \secondvar) := \sum_{i,j} G_{ij}(\firstvar, \secondvar_{ij}).
\end{aligned} 
\end{equation*}
Due to the separation of variables $y_{ij}$, we have:
\begin{equation*}
    \underset{\secondvar_{ij}\in\cY_{ij}}{\argmin} \sum_{i,j} G_{ij}(\firstvar, \secondvar_{ij}) = \bigotimes_{i, j} \argmin_{y_{ij}} \; G_{ij}(x, y_{ij}).

\begin{equation*}
    \begin{aligned}
        &\min_{\firstvar} && F_{ij}(\firstvar, \secondvar(\firstvar))\\
        &\text{s.t.} && \secondvar(\firstvar) \in \argmin_{\secondvar\in\cY_{ij}} G_{ij}(\firstvar, \secondvar).
\end{aligned} 
\end{equation*}
has value function equal to the characteristic function $\mbf{1}_{T_{ij}}$. Such polynomials and sets exist by the representability result for characteristic functions \Cref{lem:constrained-convex-construction}.

\begin{definition}[Value functions with lower-level convexity]
    \label{def:class-lower-level-convex}
    Under the same notations as in \Cref{def:class-general-value-functions}, the sets $\cC_{\property}$ are analogously defined to $\cP_{\property}$, except that the lower-level problem is constrained to be convex in the definition of the former, i.e.:
    % \begin{equation}
    %     \label{eq:convex-class}
    %     \cC^{\formule}_{\property} := \left\{h: \RR^n \to \RR \mid \begin{array}{c} \exists P, Q \text{ polynomials}, Q \text{ convex w.r.t } y, \cY \text{ $\property$ satisfy} \\\text{\Cref{assumption:well-definedness} such that } \ff_\formule = h\end{array} \right\}.
    % \end{equation}
    \begin{equation}
        \label{eq:convex-class}
        \cC_{\property} := \left\{h: \RR^n \to \RR \mid \begin{array}{c} \exists P, Q \text{ polynomials}, Q \text{ convex w.r.t } y, \cY \text{ $\property$} \text{ such that } \valbilevel = h\end{array} \right\}.
    \end{equation}

Any lower semicontinuous piece-wise polynomial function is the value function of a polynomial bilevel problem with lower-level objective convex over a bounded box, i.e.
\begin{equation*}
    \begin{aligned}
        \PP \cap \LSC \subseteq \cC_{\textup{\bounded}} \subseteq \SA \cap \LSC \cap \BC.
    \end{aligned}
\end{equation*}

Consider $f = (S, \tupfuncN)$ a lower semicontinuous piecewise polynomial function. Our construction is based on two observations:
\begin{enumerate}
    \item Given a point $x \in \RR^n$, define $\cI(x) := \{i \in \cI \mid x \in \overline{S_i}\}$ the subset of indices in which $x$ belongs to the closure of corresponding sets. Since $f$ is lower-semicontinuous, we have:
    \begin{equation}
        \label{eq:minimum-selection}
        f(x) = \min_{i \in \cI(x)} P_i(x).
    \end{equation}
    \item Similar to the proof of \Cref{theorem:compact=lsc+bc}, there exists a pair integer $N$ and a positive constant $B > 0$ such that $\max_{i = 1, \ldots, N} P_i(x) \leq B + \|x\|^N$. Thus, in the following construction, WLOG, one can assume that $P_i(x) \leq 0, \forall i = 1, \ldots, N, \forall x \in \RR^n$. Otherwise, we can consider the function $r(x) = f(x) - B - \|x\|^N$, which is also an element of $\cS$, lower-semicontinuous and all $r_i(x) = P_i(x) - B - \|x\|^N \leq 0$ for all $x$. If we can find functions $P, Q$ and a bounded box so that the corresponding bilevel problem has the value function equal to $r(x)$, then that of $(P + B + \|x\|^N, Q, \cY)$ is equal to $h$. 
\end{enumerate}
For each $i=1,\ldots, N$, since $S_i$ is semi-algebraic, so is its closure. By \Cref{lemma:closed-semi-algebraic-set}, they can be represented by:
\begin{equation}
    \label{eq:closure-elementary-set-representation}
    \bar{S_i} = \bigcup_{j \in J}\bigcap_{k \in K} \{x \mid P^i_{jk}(x) \geq 0\}.
\end{equation}
for some index sets $J, K$ and polynomials $P^i_{jk}$. These polynomials will appear in our construction.

Denote $z^i_j = (z^i_{jk})_{k \in K}$, consider the optimization problem:
\begin{equation*}
    \begin{aligned}
        \underset{z^i_j \in [0,1]^{|K|}}{\text{Minimize}} \quad && G^i_j(x,z^i_j) & = - \sum_{k \in K} P^i_{jk}(x)z^i_{jk},\\
    \end{aligned}
\end{equation*}
where $P_{jk}^i$ are polynomials defined in \eqref{eq:closure-elementary-set-representation}. Given a fixed value of $x$, the optimal value of $(z^i)^\star$ is given by:
\begin{equation*}
    (z_{jk}^i)^\star = \begin{cases}
        0 & \text{ if } P_{jk}^i(x) < 0\\
        [0,1] & \text{ if } P_{jk}^i(x) = 0\\
        1 & \text{ if } P_{jk}^i(x) > 0
    \end{cases}.
\end{equation*}
Therefore, we can conclude that:
\begin{equation}
    \label{eq:optimized-product-z-i}
    \prod_{k \in K} (z_{jk}^i)^\star = \begin{cases}
        0 & \text{ if } x \notin \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
        [0,1] & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\} \text{ and } \exists k \in K, P_{jk}^i(x) = 0\\
        1 & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\} \text{ and } \forall k \in K, P_{jk}^i(x) > 0\\
    \end{cases}.
\end{equation}
We consider the following bilevel problem:
\begin{equation}
    \label{eq:bilevel-construction-convex-bounded}
    \begin{aligned}
        P &= \sum_{(i,j) \in I \times J} P_i(x)\left(s_{ij}\prod_{k \in K} z_{jk}^i\right),\\
        Q &= (1 - \sum_{(i,j) \in I \times J} s_{ij})^2 + \sum_{(i,j) \in I \times J} G^i_j(x,z^i_j),\\
        s_{ij} & \in [0,1], \forall (i,j) \in I \times J,\\
        z_{jk}^i & \in [0,1], \forall (i,j,k) \in I \times J \times K.  
    \end{aligned}
\end{equation}
The lower-level problem is obviously convex since $(1 - \sum_{(i,j) \in I \times J} s_{ij})^2$ is convex w.r.t $s_{ij}$, $G^i_j$ is linear w.r.t $z_j^i$ and the feasible set is a hypercube.

In particular, $P_i(x)s_{ij} \leq 0$ since $s_{ij} \in [0,1]$ and $P_i(x)$ is assumed to be negative. Due to the optimistic nature of the bilevel problem and \eqref{eq:optimized-product-z-i}, we get:
\begin{equation}
    \label{eq:optimize-product-h-z}
    P_i(x)\prod_{k \in K} z_{jk}^i = \begin{cases}
        0 & \text{ if } x \notin \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
        P_i(x) & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
    \end{cases}.
\end{equation}
Moreover, any $(s_{ij})_{(i,j) \in |I| \times |J|} \in [0,1]^{|I| \times |J|}$ such that $\sum_{i,j} s_{ij} = 1$ is optimal for $Q$. Since we consider the optimistic bilevel formulation, the value of $P$ in  \eqref{eq:bilevel-construction-convex-bounded} becomes:
\begin{equation*}
    \begin{aligned}
        &\underset{s_{i,j} \geq 0, \sum s_{ij} = 1}{\min} \sum_{(i,j) \in I \times J} s_{ij} \left(P_i(x)\prod_{k \in K} z^i_{jk} \right).\\
        %\overset{\eqref{eq:optimize-product-h-z}}{=}& \underset{s_{i,j} \geq 0, \sum s_{ij} = 1}{\text{Minimize}} \sum_{(i,j) \in I \times J} s_{ij} \left(h_i(x)\mbf{1}_{x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}}\right)\\
    \end{aligned}
\end{equation*}
Thus, the value of $P$ will be equal to the smallest value of $P_i(x)\prod_{k \in K} z^i_{jk}$. This value will be equal to $f(x)$ because:
\begin{equation*}
    \begin{aligned}
        \underset{(i,j) \in I \times J}{\min} \left\{P_i(x)\prod_{k \in K} z^i_{jk}\right\} &\overset{\eqref{eq:optimize-product-h-z}}{=} \underset{(i,j) \in I \times J}{\min} \left\{P_i(x)\mbf{1}_{x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}}\right\} \\
        &\overset{\eqref{eq:closure-elementary-set-representation}}{=} \underset{i \in I}{\min} \left\{P_i(x)\mbf{1}_{x \in \overline{s_i}}\right\} \\
        &\overset{\eqref{eq:minimum-selection}}{=} f(x).
    \end{aligned}
\end{equation*}
This concludes the proof.

In the following, we show that if $f \in \PP \cap \LSC$, then $f \in \cC_{\bounded}$, which is the first inclusion. The second inclusion was already justified in \Cref{theorem:compact=lsc+bc}.

Consider $f = (S, \tupfuncN)$ a lower semicontinuous piecewise polynomial function. Our construction is based on two observations:
\begin{enumerate}
    \item Given a point $x \in \RR^n$, define $\cI(x) := \{i \in \cI \mid x \in \overline{S_i}\}$ the subset of indices in which $x$ belongs to the closure of corresponding sets. Since $f$ is lower-semicontinuous, we have:
    \begin{equation}
        \label{eq:minimum-selection}
        f(x) = \min_{i \in \cI(x)} P_i(x).
    \end{equation}
    \item Similar to the proof of \Cref{theorem:compact=lsc+bc}, there exists a pair integer $N$ and a positive constant $B > 0$ such that $\max_{i = 1, \ldots, N} P_i(x) \leq B + \|x\|^N$. Thus, in the following construction, WLOG, one can assume that $P_i(x) \leq 0, \forall i = 1, \ldots, N, \forall x \in \RR^n$. Otherwise, we can consider the function $r(x) = f(x) - B - \|x\|^N$, which is also an element of $\cS$, lower-semicontinuous and all $r_i(x) = P_i(x) - B - \|x\|^N \leq 0$ for all $x$. If we can find functions $P, Q$ and a bounded box so that the corresponding bilevel problem has the value function equal to $r(x)$, then that of $(P + B + \|x\|^N, Q, \cY)$ is equal to $h$. 
\end{enumerate}
For each $i=1,\ldots, N$, since $S_i$ is semi-algebraic, so is its closure. By \Cref{lemma:closed-semi-algebraic-set}, they can be represented by:
\begin{equation}
    \label{eq:closure-elementary-set-representation}
    \bar{S_i} = \bigcup_{j \in J}\bigcap_{k \in K} \{x \mid P^i_{jk}(x) \geq 0\}.
\end{equation}
for some index sets $J, K$ and polynomials $P^i_{jk}$. These polynomials will appear in our construction.

