Denote $z^i_j = (z^i_{jk})_{k \in K}$, consider the optimization problem:
\begin{equation*}
    \begin{aligned}
        \underset{z^i_j \in [0,1]^{|K|}}{\text{Minimize}} \quad && G^i_j(x,z^i_j) & = - \sum_{k \in K} P^i_{jk}(x)z^i_{jk},\\
    \end{aligned}
\end{equation*}
where $P_{jk}^i$ are polynomials defined in \eqref{eq:closure-elementary-set-representation}. Given a fixed value of $x$, the optimal value of $(z^i)^\star$ is given by:
\begin{equation*}
    (z_{jk}^i)^\star = \begin{cases}
        0 & \text{ if } P_{jk}^i(x) < 0\\
        [0,1] & \text{ if } P_{jk}^i(x) = 0\\
        1 & \text{ if } P_{jk}^i(x) > 0
    \end{cases}.
\end{equation*}
Therefore, we can conclude that:
\begin{equation}
    \label{eq:optimized-product-z-i}
    \prod_{k \in K} (z_{jk}^i)^\star = \begin{cases}
        0 & \text{ if } x \notin \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
        [0,1] & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\} \text{ and } \exists k \in K, P_{jk}^i(x) = 0\\
        1 & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\} \text{ and } \forall k \in K, P_{jk}^i(x) > 0\\
    \end{cases}.
\end{equation}

We consider the following bilevel problem:
\begin{equation}
    \label{eq:bilevel-construction-convex-bounded}
    \begin{aligned}
        P &= \sum_{(i,j) \in I \times J} P_i(x)\left(s_{ij}\prod_{k \in K} z_{jk}^i\right),\\
        Q &= (1 - \sum_{(i,j) \in I \times J} s_{ij})^2 + \sum_{(i,j) \in I \times J} G^i_j(x,z^i_j),\\
        s_{ij} & \in [0,1], \forall (i,j) \in I \times J,\\
        z_{jk}^i & \in [0,1], \forall (i,j,k) \in I \times J \times K.  
    \end{aligned}
\end{equation}
The lower-level problem is obviously convex since $(1 - \sum_{(i,j) \in I \times J} s_{ij})^2$ is convex w.r.t $s_{ij}$, $G^i_j$ is linear w.r.t $z_j^i$ and the feasible set is a hypercube.

In particular, $P_i(x)s_{ij} \leq 0$ since $s_{ij} \in [0,1]$ and $P_i(x)$ is assumed to be negative. Due to the optimistic nature of the bilevel problem and \eqref{eq:optimized-product-z-i}, we get:
\begin{equation}
    \label{eq:optimize-product-h-z}
    P_i(x)\prod_{k \in K} z_{jk}^i = \begin{cases}
        0 & \text{ if } x \notin \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
        P_i(x) & \text{ if } x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}\\
    \end{cases}.
\end{equation}
Moreover, any $(s_{ij})_{(i,j) \in |I| \times |J|} \in [0,1]^{|I| \times |J|}$ such that $\sum_{i,j} s_{ij} = 1$ is optimal for $Q$. Since we consider the optimistic bilevel formulation, the value of $P$ in  \eqref{eq:bilevel-construction-convex-bounded} becomes:
\begin{equation*}
    \begin{aligned}
        &\underset{s_{i,j} \geq 0, \sum s_{ij} = 1}{\min} \sum_{(i,j) \in I \times J} s_{ij} \left(P_i(x)\prod_{k \in K} z^i_{jk} \right).\\
        %\overset{\eqref{eq:optimize-product-h-z}}{=}& \underset{s_{i,j} \geq 0, \sum s_{ij} = 1}{\text{Minimize}} \sum_{(i,j) \in I \times J} s_{ij} \left(h_i(x)\mbf{1}_{x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}}\right)\\
    \end{aligned}
\end{equation*}

Thus, the value of $P$ will be equal to the smallest value of $P_i(x)\prod_{k \in K} z^i_{jk}$. This value will be equal to $f(x)$ because:
\begin{equation*}
    \begin{aligned}
        \underset{(i,j) \in I \times J}{\min} \left\{P_i(x)\prod_{k \in K} z^i_{jk}\right\} &\overset{\eqref{eq:optimize-product-h-z}}{=} \underset{(i,j) \in I \times J}{\min} \left\{P_i(x)\mbf{1}_{x \in \bigcap_{k \in K} \{P^i_{jk}(x) \geq 0\}}\right\} \\
        &\overset{\eqref{eq:closure-elementary-set-representation}}{=} \underset{i \in I}{\min} \left\{P_i(x)\mbf{1}_{x \in \overline{s_i}}\right\} \\
        &\overset{\eqref{eq:minimum-selection}}{=} f(x).
    \end{aligned}
\end{equation*}
This concludes the proof.

For each $i=1,\ldots, N$, since $S_i$ is semi-algebraic, so is its closure. By \Cref{lemma:closed-semi-algebraic-set}, they can be represented by:
\begin{equation}
    \label{eq:closure-elementary-set-representation}
    \bar{S_i} = \bigcup_{j \in J}\bigcap_{k \in K} \{x \mid P^i_{jk}(x) \geq 0\}.
\end{equation}
for some index sets $J, K$ and polynomials $P^i_{jk}$. These polynomials will appear in our construction.

\begin{theorem}[Value functions of  box-constrained polynomial bilevel programming]
    \label{theorem:compact=lsc+bc}
    Any function which is semi-algebraic, lower semicontinuous, and bounded on compact sets is the value function of a polynomial bilevel problem whose lower-level feasible set $\cY$ is a bounded box. In other words:
    \begin{equation*}
        \cP_{\textup{\bounded}} = \SA \cap \LSC \cap \BC.
    \end{equation*}
\end{theorem}

